"""Identifier-rewriting reducer used by Vulcan."""

from __future__ import annotations

from collections import Counter
from string import ascii_lowercase, ascii_uppercase
from typing import Iterator

from reduction.grammar import Grammar
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree import SparTreeNode
from reduction.tree_utils import rewrite_source_tokens


class IdentifierReplacementReducer(AbstractReducer):
    """Replace identifiers with shorter names when the property survives."""

    def __init__(self, grammar: Grammar):
        self.grammar = grammar
        self.parser = Parser(grammar)

    @property
    def name(self) -> str:
        return "vulcan_identifier_replacement"

    def reduce(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode:
        current_source = tree.to_source()
        changed = False
        identifiers = self._ordered_identifiers(tree)

        for replacement_name, identifier in zip(self._short_names(), identifiers):
            if identifier == replacement_name:
                continue

            def transform(token) -> str | None:
                if token.type == "IDENTIFIER" and token.value == identifier:
                    return replacement_name
                return None

            candidate_source = rewrite_source_tokens(current_source, transform)
            if candidate_source == current_source:
                continue
            if tester.test(candidate_source):
                current_source = candidate_source
                changed = True

        if not changed:
            return tree.clone()
        return self.parser.parse(current_source)

    def _ordered_identifiers(self, tree: SparTreeNode) -> list[str]:
        counts = Counter(
            token.value
            for token in tree.tokens()
            if token.type == "IDENTIFIER"
        )
        return [
            identifier
            for identifier, _ in sorted(
                counts.items(),
                key=lambda item: (-item[1], -len(item[0]), item[0]),
            )
        ]

    def _short_names(self) -> Iterator[str]:
        for name in ascii_lowercase + ascii_uppercase + "_":
            yield name

        alphabet = ascii_lowercase
        width = 2
        while True:
            pool_size = len(alphabet) ** width
            for value in range(pool_size):
                current = value
                chars = []
                for _ in range(width):
                    chars.append(alphabet[current % len(alphabet)])
                    current //= len(alphabet)
                yield "".join(reversed(chars))
            width += 1

