"""Compatible subtree replacement used by Vulcan."""

from __future__ import annotations

from reduction.grammar import Grammar
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree import SparTreeNode
from reduction.tree_utils import (
    iter_nodes,
    line_span,
    reindent_lines,
    replace_lines,
    target_indent_for,
)


class SubtreeReplacementReducer(AbstractReducer):
    """Replace non-leaf nodes with smaller compatible subtrees."""

    def __init__(self, grammar: Grammar):
        self.grammar = grammar
        self.parser = Parser(grammar)

    @property
    def name(self) -> str:
        return "vulcan_subtree_replacement"

    def reduce(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode:
        working = tree.clone()
        while True:
            source = working.to_source()
            changed = False
            nodes = [
                (path, node)
                for path, node in iter_nodes(working)
                if path and not node.deleted and node.children and node.token_count() > 0
            ]
            nodes.sort(key=lambda item: item[1].token_count(), reverse=True)

            for path, node in nodes:
                span = line_span(node)
                if span is None:
                    continue
                target_indent = target_indent_for(node)
                seen_replacements: set[tuple[str, ...]] = set()
                candidates = [
                    candidate
                    for candidate in nodes
                    if candidate[0] != path
                    and candidate[1].rule_name == node.rule_name
                    and candidate[1].token_count() < node.token_count()
                ]
                candidates.sort(key=lambda item: item[1].token_count())

                for _, candidate_node in candidates:
                    candidate_source = candidate_node.to_source().rstrip("\n")
                    if not candidate_source:
                        continue
                    replacement_lines = tuple(
                        reindent_lines(candidate_source.splitlines(), target_indent)
                    )
                    if replacement_lines in seen_replacements:
                        continue
                    seen_replacements.add(replacement_lines)
                    candidate_program = replace_lines(
                        source,
                        span[0],
                        span[1],
                        replacement_lines,
                    )
                    if not candidate_program or candidate_program == source:
                        continue
                    if tester.test(candidate_program):
                        working = self.parser.parse(candidate_program)
                        changed = True
                        break
                if changed:
                    break
            if not changed:
                return working

