"""Common-token reduction for PPR."""

from __future__ import annotations

from reduction.property_test import PropertyTester
from reduction.tree_utils import rewrite_source_tokens
from ppr.diff_utils import common_tokens


class MinCommonality:
    """Delete shared tokens from both programs when both properties survive."""

    def reduce(
        self,
        seed_source: str,
        variant_source: str,
        seed_tester: PropertyTester,
        variant_tester: PropertyTester,
    ) -> tuple[str, str]:
        current_seed = seed_source
        current_variant = variant_source

        while True:
            progress = False
            occurrences_seen: dict[str, int] = {}
            for token_value in common_tokens(current_seed, current_variant):
                occurrences_seen[token_value] = occurrences_seen.get(token_value, 0) + 1
                occurrence = occurrences_seen[token_value]
                candidate_seed = self._delete_occurrence(current_seed, token_value, occurrence)
                candidate_variant = self._delete_occurrence(current_variant, token_value, occurrence)
                if candidate_seed == current_seed or candidate_variant == current_variant:
                    continue
                if seed_tester.test(candidate_seed) and variant_tester.test(candidate_variant):
                    current_seed = candidate_seed
                    current_variant = candidate_variant
                    progress = True
                    break
            if not progress:
                return current_seed, current_variant

    def _delete_occurrence(self, source: str, token_value: str, occurrence: int) -> str:
        seen = 0

        def transform(token) -> str | None:
            nonlocal seen
            if token.type == "NEWLINE":
                return None
            if token.value != token_value:
                return None
            seen += 1
            if seen == occurrence:
                return ""
            return None

        return rewrite_source_tokens(source, transform)

